import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import Button from 'flarum/common/components/Button';
import app from 'flarum/admin/app';
export default class SettingsPage extends ExtensionPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.categories = [];
    this.loadCategories();
  }
  async loadCategories() {
    this.categories = await app.store.find('ticket-categories');
    m.redraw();
  }
  content() {
    return m("div", {
      className: "ExtensionPage-settings"
    }, m("div", {
      className: "Form"
    }, m("h3", null, app.translator.trans('cengizkemec-support.admin.settings')), this.buildSettingComponent({
      setting: 'cengizkemec-support.auto_close_days',
      type: 'number',
      label: app.translator.trans('cengizkemec-support.admin.auto_close_days'),
      min: 1,
      max: 365
    }), this.buildSettingComponent({
      setting: 'cengizkemec-support.email_notifications',
      type: 'boolean',
      label: app.translator.trans('cengizkemec-support.admin.email_notifications')
    }), m("div", {
      className: "Form-group"
    }, this.submitButton()), m("hr", null), m("h3", null, app.translator.trans('cengizkemec-support.admin.categories')), m("ul", null, this.categories.map(cat => m("li", {
      key: cat.id()
    }, cat.name(), " (", cat.slug(), ")", m(Button, {
      className: "Button Button--danger Button--small",
      onclick: () => this.deleteCategory(cat)
    }, "Delete")))), m(Button, {
      className: "Button Button--primary",
      onclick: () => this.createCategory()
    }, "Add Category")));
  }
  async createCategory() {
    const name = prompt('Category name');
    if (!name) return;
    const slug = name.toLowerCase().replace(/\s+/g, '-');
    await app.store.createRecord('ticket-categories').save({
      name,
      slug,
      isActive: true
    });
    this.loadCategories();
  }
  async deleteCategory(cat) {
    if (confirm('Delete this category?')) {
      await cat.delete();
      this.loadCategories();
    }
  }
}
flarum.reg.add('cengizkemec-support-tickets', 'admin/components/SettingsPage', SettingsPage);